-- dev_032_pallet_stock_safety: COMBINED DEVELOPMENT MIGRATION for shipbay-nexus-dev (gdoaonsasbsperqjuurm) ONLY. NOT APPLIED.
-- Generated by supabase/dev/pending/build.sh from the two files below; do not edit by hand.
--   1. supabase/candidates/20261204_wms_pallet_stock_safety.sql  (wms_void_pallet, wms_set_units, new wms_correct_units)
--   2. supabase/dev/movement-dev.sql: the two helpers that changed since dev_029 (dev_movement_snapshot reports which safety
--      rules are installed; dev_runner_begin knows the 'undo' stage)
-- It replaces three functions and adds one. No table, row, pallet, stock entry or journal entry is touched. No DROP.
-- Apply as one migration (one transaction). Afterwards every function body must match the candidate (md5 of prosrc).

-- ===== 1. candidate 20261204 =====
-- Pallet stock safety: the void and the unit count. CANDIDATE: tested on the local synthetic database only, applied nowhere.
-- Part 1 (void) accepted by Derek as locally tested at commit f08a83f; part 2 (unit count) requested 2026-11-23 1:26 AM.
-- Needs 20261127_wms_waves (pallet on picks), 20261130_wms_nexus_putaway (the journal) and 20261203_wms_inventory_workflow (_wms_pallet_busy).
-- Derek's request, 2026-11-23 1:14 AM.
--
-- What a void does today: wms_void_pallet only sets the pallet's status. The stock trigger then sees a pallet that is not
-- 'stored' and takes everything the pallet ever posted off the books as one 'adjust'. Picks made from the pallet are separate
-- ledger rows and stay. So:
--   1. 100 received, 30 picked, void: the position is left at minus 30.
--   2. Void while a Nexus request is waiting: on a move the stock is written off at once, Nexus completes the move, and ShipBay
--      then refuses to record it ("was voided"): a void pallet at the old position in ShipBay, the new position held in Nexus.
--
-- The rule: a void is for a pallet entered by mistake. It is refused, with nothing changed, when
--   a. a Nexus request for the pallet is not settled (waiting for an answer, or accepted by Nexus and not recorded by ShipBay);
--   b. the pallet has left the building (its units are settled by the outbound transaction, never by a void);
--   c. a wave still has a pick planned from it;
--   d. units have been picked from it and not put back (the picks are its history; undo them first);
--   e. taking its units off the books would leave any position below zero (older picks that named no pallet).
-- A void that passes posts exactly what it posted before. Nothing else in the function changed: same login check, same reason
-- rule, same row returned, same grants. Reconciliation is untouched: record and undo for an out-of-sync request work as before,
-- and once the request is settled the pallet can be voided if the other rules allow it.

create or replace function public.wms_void_pallet(p_id uuid, p_reason text) returns public.wms_pallets
language plpgsql security definer set search_path to 'public' as $$
declare r wms_pallets; p wms_pallets; o wms_nexus_ops; v_wave int; v_picked int; x record;
begin
  if not is_wms_staff() then raise exception 'This login cannot void pallets.'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Say why this pallet is being voided.'; end if;
  -- the same row lock every Nexus request takes first: a void and a scan for the same pallet cannot pass each other
  select * into p from wms_pallets where id = p_id for update;
  if p.id is null or p.status = 'void' then raise exception 'That pallet is not on file or is already voided.'; end if;

  -- a. not while Nexus has not settled where it stands
  select * into o from wms_nexus_ops where pallet_id = p.id and state in ('pending', 'out_of_sync') order by (state = 'out_of_sync') desc, created_at limit 1;
  if o.id is not null then
    if o.state = 'out_of_sync' then
      raise exception '% cannot be voided yet: Nexus accepted % and ShipBay has not recorded it. An admin settles that under Put away first.', p.psku, coalesce(o.to_code, o.from_code);
    end if;
    raise exception '% cannot be voided yet: it has a request for % that Nexus has not answered. Finish that one first.', p.psku, coalesce(o.to_code, o.from_code);
  end if;

  -- b. a pallet that left the building keeps its record
  if p.status = 'departed' then raise exception '% has left the building and cannot be voided. Its record stays as it is.', p.psku; end if;

  -- c. a pick is planned from it
  select min(w.seq) into v_wave from wms_wave_tasks t join wms_waves w on w.id = t.wave_id where t.pallet_id = p.id and t.confirmed_at is null and w.status = 'picking';
  if v_wave is not null then raise exception 'Wave % still has a pick planned from %. Pick that stop or hand the wave back first.', v_wave, p.psku; end if;

  -- d. units picked from it and not put back
  select -coalesce(sum(m.qty), 0)::int into v_picked from inventory_moves m where m.pallet_id = p.id and m.reason = 'pick';
  if v_picked <> 0 then
    raise exception '% of %''s units have been picked. A pallet that has been picked from cannot be voided: undo those picks first.', v_picked, p.psku;
  end if;

  -- e. nothing may end below zero (picks that named no pallet, made with the older pick list)
  for x in
    select s.sku, coalesce(l.code, 'no position') code, d.qty posted,
      (select coalesce(sum(m.qty), 0)::int from inventory_moves m where m.sku_id = d.sku_id and m.location_id is not distinct from d.location_id) on_books
    from (select m.sku_id, m.location_id, sum(m.qty)::int qty from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id group by 1, 2 having sum(m.qty) > 0) d
    join skus s on s.id = d.sku_id left join locations l on l.id = d.location_id
  loop
    if x.on_books < x.posted then
      raise exception '% cannot be voided: it put % of % at % and only % are on the books there. Units have been picked from that position. Undo those picks first.', p.psku, x.posted, x.sku, x.code, x.on_books;
    end if;
  end loop;

  update wms_pallets set status = 'void', voided_at = now(), voided_by = auth.uid(), void_reason = trim(p_reason)
   where id = p_id and status <> 'void' returning * into r;
  if r.id is null then raise exception 'That pallet is not on file or is already voided.'; end if;
  return r;
end $$;


-- ---------------------------------------------------------------------------------------------------------------------------
-- Part 2: the unit count.
--
-- What it does today: wms_set_units changes units per carton (or units on the pallet) and re-posts the pallet's stock. Any floor
-- login, no reason, no checks. On a pallet that is put away the difference goes onto the books as an 'adjust' at once, so:
--   1. 100 received, 30 picked, count set to 2 per carton (20): the position is left at minus 10.
--   2. A wave has 12 planned from it and the count is cut to nothing: the stop is planned against stock that is no longer there.
--   3. While a Nexus request is waiting the count, and the stock, can change under a movement that is not settled.
--   4. A pallet that left the shared floor: the cartons change and the ledger does not, so the two disagree from then on.
--
-- The rule, in two functions with the existing one keeping its name and arguments:
--   wms_set_units (any floor login, as today): entering or fixing the count BEFORE the pallet holds stock, and the first count
--     of a put-away pallet that never had one. Refused for a put-away pallet that is already counted (that is a correction,
--     below), while a Nexus request for it is not settled, and after it has left the shared floor or the building.
--   wms_correct_units (ShipBay admin or staff, reason required): changing the count of a pallet that IS put away. Refused while
--     a Nexus request is not settled. It posts the same difference the old function posted, then checks the result and takes
--     everything back if: the pallet would hold fewer units of a product than have been picked from it plus what waves still
--     plan to pick from it, or any position would end below what waves have planned there (and so never below zero).
--     The reason goes on the ledger row and into the activity log with the old and new count and who did it.
-- Nothing else changed: the stock function, the triggers, receiving, counting, put-away and every quantity they post.

create or replace function public.wms_set_units(p_pallet uuid, p_item text, p_units integer) returns integer
language plpgsql security definer set search_path to 'public' as $$
declare p wms_pallets; o wms_nexus_ops; v_n int; v_item text := nullif(trim(p_item), '');
begin
  if not is_wms_staff() then raise exception 'This login cannot change a pallet.'; end if;
  if p_units is null or p_units < 0 or p_units > 1000000 then raise exception 'Units must be a whole number.'; end if;
  select * into p from wms_pallets where id = p_pallet for update;
  if p.id is null then raise exception 'Pallet not found.'; end if;
  if p.status = 'void' then raise exception '% is void.', p.psku; end if;
  -- added: the safety rules
  select * into o from wms_nexus_ops where pallet_id = p.id and state in ('pending', 'out_of_sync') order by (state = 'out_of_sync') desc, created_at limit 1;
  if o.id is not null then
    if o.state = 'out_of_sync' then raise exception '% cannot be changed yet: Nexus accepted % and ShipBay has not recorded it. An admin settles that under Put away first.', p.psku, coalesce(o.to_code, o.from_code); end if;
    raise exception '% cannot be changed yet: it has a request for % that Nexus has not answered. Finish that one first.', p.psku, coalesce(o.to_code, o.from_code);
  end if;
  if p.status = 'departed' then raise exception '% has left the building. Its count stays as it is.', p.psku; end if;
  if p.status = 'off_floor' then raise exception '% is off the shared floor. Put it away again before changing its count.', p.psku; end if;
  -- put away and already counted: a change is a stock correction. (A first count on a put-away pallet that never had one is still entry: it can only add.)
  if p.status = 'stored' and (
       exists (select 1 from wms_cartons c where c.pallet_id = p.id and ((v_item is null and not p.mixed) or c.item_no = v_item) and c.units_per_carton is not null)
       or (p.units_total is not null and not exists (select 1 from wms_cartons c where c.pallet_id = p.id))) then
    raise exception '% is put away, so changing its count changes stock. A ShipBay admin or staff login corrects it, with a reason.', p.psku;
  end if;
  -- from here on: unchanged
  if exists (select 1 from wms_cartons c where c.pallet_id = p.id) then
    update wms_cartons c set units_per_carton = p_units
    where c.pallet_id = p.id and ((v_item is null and not p.mixed) or c.item_no = v_item);
    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception 'That product is not on %.', p.psku; end if;
    if not p.mixed and not p.cle then update wms_pallets set units_per_carton = p_units where id = p.id; end if;
  else
    update wms_pallets set units_total = p_units where id = p.id;
  end if;
  return _wms_post_stock(p.id);
end $$;

create or replace function public.wms_correct_units(p_pallet uuid, p_item text, p_units integer, p_reason text) returns jsonb
language plpgsql security definer set search_path to 'public' as $$
declare p wms_pallets; o wms_nexus_ops; v_n int; v_item text := nullif(trim(p_item), ''); v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_name text; v_before uuid[]; v_old int; v_change int; x record;
begin
  if not wms_nexus_admin() then raise exception 'Only ShipBay admin or staff can correct the count of a pallet that is put away.'; end if;
  if v_reason is null or length(v_reason) < 4 then raise exception 'Say why the count is being corrected.'; end if;
  if p_units is null or p_units < 0 or p_units > 1000000 then raise exception 'Units must be a whole number.'; end if;
  select * into p from wms_pallets where id = p_pallet for update;   -- the same row lock every Nexus request takes first
  if p.id is null then raise exception 'Pallet not found.'; end if;
  if p.status = 'void' then raise exception '% is void.', p.psku; end if;
  select * into o from wms_nexus_ops where pallet_id = p.id and state in ('pending', 'out_of_sync') order by (state = 'out_of_sync') desc, created_at limit 1;
  if o.id is not null then
    if o.state = 'out_of_sync' then raise exception '% cannot be corrected yet: Nexus accepted % and ShipBay has not recorded it. An admin settles that under Put away first.', p.psku, coalesce(o.to_code, o.from_code); end if;
    raise exception '% cannot be corrected yet: it has a request for % that Nexus has not answered. Finish that one first.', p.psku, coalesce(o.to_code, o.from_code);
  end if;
  if p.status = 'departed' then raise exception '% has left the building. Its count stays as it is.', p.psku; end if;
  if p.status = 'off_floor' then raise exception '% is off the shared floor. Put it away again before correcting its count.', p.psku; end if;
  if p.status <> 'stored' or p.location_id is null then raise exception '% is not put away yet. Enter its count the usual way.', p.psku; end if;

  select coalesce(array_agg(m.id), '{}') into v_before from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id;
  -- the same change the count screen makes
  if exists (select 1 from wms_cartons c where c.pallet_id = p.id) then
    select max(c.units_per_carton) into v_old from wms_cartons c where c.pallet_id = p.id and ((v_item is null and not p.mixed) or c.item_no = v_item);
    update wms_cartons c set units_per_carton = p_units
    where c.pallet_id = p.id and ((v_item is null and not p.mixed) or c.item_no = v_item);
    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception 'That product is not on %.', p.psku; end if;
    if not p.mixed and not p.cle then update wms_pallets set units_per_carton = p_units where id = p.id; end if;
  else
    v_old := p.units_total;
    update wms_pallets set units_total = p_units where id = p.id;
  end if;
  perform _wms_post_stock(p.id);   -- posts nothing more if the triggers already did
  select coalesce(sum(m.qty), 0)::int into v_change from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before));

  -- the result must be stock that exists. Anything else raises, and the whole change is taken back.
  for x in
    select s.sku, d.qty holds,
      (select -coalesce(sum(m.qty), 0)::int from inventory_moves m where m.pallet_id = p.id and m.reason = 'pick' and m.sku_id = d.sku_id) picked,
      (select coalesce(sum(t.qty_planned), 0)::int from wms_wave_tasks t join wms_waves w on w.id = t.wave_id where t.pallet_id = p.id and t.sku_id = d.sku_id and t.confirmed_at is null and w.status = 'picking') planned
    from (select m.sku_id, sum(m.qty)::int qty from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id group by 1) d join skus s on s.id = d.sku_id
  loop
    if x.holds < x.picked + x.planned then
      raise exception 'That would make % hold % of %, and % have been picked from it%. The count cannot go below that.', p.psku, x.holds, x.sku, x.picked,
        case when x.planned > 0 then ' with ' || x.planned || ' more planned by a wave' else '' end;
    end if;
  end loop;
  for x in
    select s.sku, coalesce(l.code, 'no position') code,
      (select coalesce(sum(m.qty), 0)::int from inventory_moves m where m.sku_id = d.sku_id and m.location_id is not distinct from d.location_id) on_books,
      (select coalesce(sum(t.qty_planned), 0)::int from wms_wave_tasks t join wms_waves w on w.id = t.wave_id where t.sku_id = d.sku_id and t.location_id = d.location_id and t.confirmed_at is null and w.status = 'picking') planned
    from (select distinct m.sku_id, m.location_id from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id) d join skus s on s.id = d.sku_id left join locations l on l.id = d.location_id
  loop
    if x.on_books < x.planned then
      raise exception 'That would leave % of % at %, and % are needed there%. The count cannot go that low.', x.on_books, x.sku, x.code, greatest(x.planned, 0),
        case when x.planned > 0 then ' for picks a wave has planned' else ' (it cannot go below zero)' end;
    end if;
  end loop;

  if v_change <> 0 then
    select coalesce(full_name, email) into v_name from profiles where id = auth.uid();
    update inventory_moves m set note = left(p.psku || ' count corrected: ' || v_reason, 200) where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before));
    insert into wms_activity (org_id, kind, qty, ref, actor, actor_name, detail) values (p.org_id, 'pallet_units_corrected', abs(v_change), p.psku, auth.uid(), v_name,
      jsonb_build_object('item', v_item, 'from', v_old, 'to', p_units, 'units_change', v_change, 'position', (select code from locations where id = p.location_id), 'reason', v_reason));
  end if;
  return jsonb_build_object('pallet', p.psku, 'units_change', v_change, 'from', v_old, 'to', p_units);
end $$;
revoke all on function public.wms_correct_units(uuid, text, integer, text) from public, anon;
grant execute on function public.wms_correct_units(uuid, text, integer, text) to authenticated;

-- ===== 2. dev helpers changed since dev_029 =====
create or replace function public.dev_movement_snapshot() returns jsonb language plpgsql stable security definer set search_path to 'public' as $$
declare j jsonb;
begin
  perform _dev_synthetic_only();
  select jsonb_build_object(
    'pallets', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'psku', p.psku, 'status', p.status, 'held', p.held, 'location', l.code, 'batch', p.batch_key, 'pos', p.batch_pos,
        'org', p.org_id, 'carton', (select min(c.code) from wms_cartons c where c.pallet_id = p.id),
        'receipts', (select count(*) from inventory_moves m where m.ref_id = p.id and m.reason = 'receive'),
        'received_units', (select coalesce(sum(m.qty), 0) from inventory_moves m where m.ref_id = p.id and m.reason = 'receive'),
        'adjustments', (select count(*) from inventory_moves m where m.ref_id = p.id and m.reason = 'adjust'),
        'transfers', (select count(*) from inventory_moves m where m.ref_id = p.id and m.reason = 'transfer'),
        'transfer_net', (select coalesce(sum(m.qty), 0) from inventory_moves m where m.ref_id = p.id and m.reason = 'transfer'),
        'ledger_rows', (select count(*) from inventory_moves m where m.ref_id = p.id or m.pallet_id = p.id),
        'on_books', (select coalesce(sum(m.qty), 0) from inventory_moves m where m.ref_id = p.id or m.pallet_id = p.id)) order by p.psku), '[]')
      from wms_pallets p left join locations l on l.id = p.location_id),
    'stock', (select coalesce(jsonb_agg(jsonb_build_object('sku', x.sku, 'location', x.code, 'qty', x.qty) order by x.sku, x.code), '[]')
      from (select s.sku, l.code, sum(m.qty)::int qty from inventory_moves m join skus s on s.id = m.sku_id left join locations l on l.id = m.location_id group by 1, 2 having sum(m.qty) <> 0) x),
    'by_sku', (select coalesce(jsonb_object_agg(x.sku, x.qty), '{}') from (select s.sku, sum(m.qty)::int qty from inventory_moves m join skus s on s.id = m.sku_id group by 1) x),
    'by_reason', (select coalesce(jsonb_object_agg(x.reason, jsonb_build_object('rows', x.n, 'units', x.qty)), '{}') from (select reason, count(*) n, sum(qty)::int qty from inventory_moves group by 1) x),
    'ledger_rows', (select count(*) from inventory_moves),
    'ledger_units', (select coalesce(sum(qty), 0) from inventory_moves),
    'ops', (select coalesce(jsonb_agg(jsonb_build_object('op', o.id, 'psku', o.psku, 'kind', o.kind, 'state', o.state, 'from', o.from_code, 'to', o.to_code, 'key', o.idem_key, 'attempts', o.attempts,
        'http', o.nexus_http, 'error', o.nexus_error, 'problem', o.problem, 'reason', o.reason, 'confirmed', o.confirmed_at_position, 'fixes', o.fixes, 'by', o.by_name,
        'resolution', o.resolution, 'resolved_by', o.resolved_by_name) order by o.created_at, o.id), '[]') from wms_nexus_ops o),
    'left_floor_log', (select coalesce(jsonb_agg(jsonb_build_object('psku', a.ref, 'from', a.detail ->> 'from', 'reason', a.detail ->> 'reason', 'units_on_books', a.detail -> 'units_on_books') order by a.id), '[]')
      from wms_activity a where a.kind = 'pallet_left_floor'),
    'off_floor', (select jsonb_build_object('exists', true, 'pickable', l.pickable, 'shared', coalesce(l.shared, false)) from locations l where l.code = 'OFF-FLOOR'),
    'orders', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'number', o.order_number, 'status', o.status, 'org', o.org_id) order by o.order_number), '[]') from orders o),
    -- which safety rules this database has (read from the function text; the suite's preflight refuses to start without them)
    'rules', jsonb_build_object(
      'void_safety', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'wms_void_pallet' and prosrc like '%cannot be voided yet%'),
      'unit_safety', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'wms_set_units' and prosrc like '%cannot be changed yet%')
        and exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'wms_correct_units'))
  ) into j;
  return j;
end $$;

create or replace function public.dev_runner_begin(p_stage text) returns bigint language plpgsql security definer set search_path to 'public' as $$
declare v bigint;
begin
  perform _dev_synthetic_only();
  if p_stage not in ('preflight', 'move', 'release', 'lost', 'partial', 'undo', 'picks', 'stops', 'final') then raise exception 'Unknown stage.'; end if;
  if exists (select 1 from dev_runner_runs where finished_at is null and started_at > now() - interval '10 minutes') then raise exception 'A stage is still running. Nothing was started.'; end if;
  if p_stage not in ('preflight', 'final') and exists (select 1 from dev_runner_runs where stage = p_stage) then raise exception 'Stage % was already started once. Nothing was started.', p_stage; end if;
  insert into dev_runner_runs (stage) values (p_stage) returning id into v; return v;
end $$;
